package main

import (
	"log"
	"log/slog"
	"os"
)

func main() {
	// 1. 标准 logger：统一前缀、加上文件行号
	log.SetPrefix("[demo] ")
	log.SetFlags(log.LstdFlags | log.Lshortfile)
	log.Println("标准日志启动")

	// 2. 独立 logger：自定义输出目标和时间精度
	audit := log.New(os.Stdout, "[audit] ", log.Ltime|log.Lmicroseconds)
	audit.Println("审计日志：服务启动")

	// 3. slog：JSON 输出 + 固定字段 + 分组
	level := new(slog.LevelVar)
	handler := slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: level})
	logger := slog.New(handler).With("service", "order")
	logger.Info("服务启动", "port", 8080)
	logger.WithGroup("db").Info("连接成功", "rows", 3)

	// 4. 运行时把级别降到 Debug
	level.Set(slog.LevelDebug)
	logger.Debug("调试日志已打开")

	// 5. 全局换成 slog 后，老 log 调用也会输出成 JSON
	slog.SetDefault(logger)
	log.Println("这行由 slog 输出")

	logger.Error("演示错误日志", "err", "库存不足")
}
